import sys; from ray import tune; import optax
sys.path.append('storage/krono')
from default_cnn_inputnorm import DefaultCNN_InputNorm # Use the network script from storage

# This submission RELIES ON THE SYSTEM'S DEFAULT training_step
# No training_step function is provided.

def _define_hyperparameters():
    return {
        'learning_rate': tune.choice([4e-4]),
        'entropy_coef': tune.choice([0.01]),
        'value_loss_coef': tune.choice([0.5]),
        'cnn_features_1': tune.choice([32]),
        'cnn_features_2': tune.choice([64]),
    }

def create_network(hparams):
    return DefaultCNN_InputNorm(
        cnn_features_1=hparams['cnn_features_1'],
        cnn_features_2=hparams['cnn_features_2']
    )

def create_optimizer(learning_rate: float = 4e-4):
    return optax.adam(learning_rate=learning_rate, eps=1e-5)

BASE_SEED = 3028
